    "explanation": "정답은 ①이다. H&E 사진에는 옅고 거품처럼 보이는 세포질을 가진 조직구가 군집을 이루고 있다. 항산균 염색 사진에서는 세포질 안의 가늘고 붉은 막대들을 특히 아래쪽 중앙과 왼쪽 영역에서 찾을 수 있다. 피부·말초신경 관련 임상과 함께, 이런 대식세포성 반응은 나종형 나병(lepromatous leprosy)의 양상에 합당하다. 나균에 대한 세포매개면역이 약해 대식세포가 균을 충분히 억제하지 못하는 방향의 반응이다.\n\n② 결핵형 나병(tuberculoid leprosy)은 상대적으로 강한 나균 특이 세포면역, 잘 형성된 육아종, 적은 균량과 연결한다. ③ 사진의 주된 세포는 호중구가 아니다. ④ 세포 안에 균이 보이는 상태를 곧 감염 해소로 해석할 수 없다. ⑤ 항산균 염색의 가는 균을 핵내봉입체와 혼동하면 안 되며, CMV 감염 역시 면역 상태와 관련이 있다.\n\n보충 검토: 나종형의 면역 저하는 나균에 대한 반응을 중심으로 이해하며, 곧바로 전신의 모든 T세포 기능 결핍을 뜻하지 않는다. 이 AFB 사진에서 개별 균의 모양만으로 M. leprae를 종 수준까지 동정할 수도 없다. 원문에서 제시한 진단 맥락과 임상·조직 반응을 함께 이용한 문제이다. 두 사진은 아래 출처의 파일 내부 PDF p.10이다.",
