    "explanation": "정답 ③. 생후 6주 영아는 중증 백일해 고위험군이며, 그 영아에게 전파할 수 있는 가족도 노출 후 예방 대상 여부를 신속히 평가해야 한다. 접종력만으로 이를 면제하지 않는다. 환자는 적절한 항균제 치료 시작 후 5일까지 비말주의가 필요하다.\n① 모체 항체·백신은 위험을 낮추지만 노출 후 예방적 항균제를 대체하지 않는다. 영아의 접종 일정도 별도로 관리한다.\n② 고위험 접촉자의 예방 조치를 PCR 결과까지 미룰 이유가 없고, 기침의 강도는 격리 해제 기준이 아니다.\n③ 강의의 고위험군 중심 접촉자 예방과 환자의 치료 후 격리 기준을 함께 적용했다.\n④ Tdap을 맞았어도 감염·전파가 가능하다. 림프구수는 적절한 치료 후 전염성 감소를 대신하는 기준이 아니다.\n⑤ 접촉자 예방과 환자 치료는 서로 보완한다. 환자의 균 제거와 영아 보호를 함께 수행한다.\n국내 강의는 고위험군 및 이들에게 전파할 위험이 있는 집단을 강조한다. CDC는 가정 내 무증상 접촉자에 대해 더 넓은 PEP 범위를 명시한다. 이 가정은 영아 고위험 접촉이 있어 두 접근 모두 예방 평가가 필요하다.\n참고: CDC Pertussis PEP — https://www.cdc.gov/pertussis/php/postexposure-prophylaxis/",
